toolCall.argumentsJson:
{"CommandLine":"$dirs = @(
    "E:\AI_BS_Resources\Studio_Media\Raw_Captures",
    "E:\AI_BS_Resources\Studio_Media\Proxies",
    "E:\AI_BS_Resources\Studio_Media\Audio_Stems",
    "C:\AI-BS\documents\media_transcripts",
    "C:\AI-BS\documents\studio_manifests",
    "C:\AI-BS\documents\technical_manuals",
    "C:\AI-BS\documents\operational_plans"
)
foreach ($d in $dirs) {
    if (!(Test-Path $d)) {
        New-Item -ItemType Directory -Force -Path $d | Out-Null
        Write-Host "Created: $d"
    }
}

$srcStreamlabs = "C:\Users\footb\AppData\Local\Google\Chrome\User Data\Default\IndexedDB\https_videoeditor.streamlabs.com_0.indexeddb.blob\2\00"
$dst = "E:\AI_BS_Resources\Studio_Media\Raw_Captures"

$mapping = @{
    "6" = "streamlabs_capture_01_20260417.mp4"
    "7" = "streamlabs_capture_02_20260417.mp4"
    "8" = "streamlabs_capture_03_20260417.mp4"
    "4" = "streamlabs_aux_04.mp4"
    "5" = "streamlabs_aux_05.mp4"
}

foreach ($k in $mapping.Keys) {
    $srcFile = Join-Path $srcStreamlabs $k
    $dstFile = Join-Path $dst $mapping[$k]
    if (Test-Path $srcFile) {
        Write-Host "Copying $srcFile -> $dstFile ..."
        Copy-Item -Path $srcFile -Destination $dstFile -Force
        $fi = Get-Item $dstFile
        Write-Host "Verified: $($mapping[$k]) ($([math]::Round($fi.Length/1GB, 2)) GB)"
    }
}

$vislaSrc = "C:\Users\footb\AppData\Local\Google\Chrome\User Data\Default\IndexedDB\https_app.visla.us_0.indexeddb.blob"
$vislaDst = "E:\AI_BS_Resources\Studio_Media\Raw_Captures\Visla"
if (!(Test-Path $vislaDst)) { New-Item -ItemType Directory -Force -Path $vislaDst | Out-Null }
if (Test-Path $vislaSrc) {
    Write-Host "Copying Visla blobs..."
    Copy-Item -Path "$vislaSrc\*" -Destination $vislaDst -Recurse -Force
    $vislaSize = (Get-ChildItem $vislaDst -Recurse -File | Measure-Object -Property Length -Sum).Sum / 1GB
    Write-Host "Verified Visla: $([math]::Round($vislaSize, 2)) GB"
}","Cwd":"C:\AI-BS","IsDaemon":false,"WaitMsBeforeAsync":10000,"toolAction":"Copying media to Drive E","toolSummary":"Extract and copy Chrome video blobs to Drive E"}
